\documentclass{article}
\usepackage{pgfplots}
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\begin{document}
\pagestyle{empty}
\begin{tikzpicture}

\begin{axis}[
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
tick style={thin, black!50},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
%grid = both,
xmin = -3.75,
xmax = 5.75,
ymin = -2.75,
ymax = 6.75,
xtick = {-10,10},
minor xtick={-9,-7,-5,-3,-1,1,3,5,7,9},
ytick = {-10,10},
minor ytick={-9,-7,-5,-3,-1,1,3,5,7,9},
xlabel = $x$,
ylabel = {$y$},
%% Here, we can control the positioning of each individual tick.
y tick label style={xshift={(\tick==6)*15pt}},
y tick label style={xshift={(\tick==4)*15pt}},
y tick label style={xshift={(\tick==2)*15pt}},
y tick label style={xshift={(\tick==-2)*18pt}},
xlabel style={below right},
ylabel style={above left},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
}
]

\addplot [domain=-10:10, samples=300, color=deepskyblue, line width=1pt]
{(x-1)^2};

\coordinate [label={below: $(1,0)$}] (A) at (axis cs:1,0);
\node[circle,color=deepskyblue,fill=deepskyblue,inner sep=1.5pt] at (A) {};

\end{axis}

\end{tikzpicture}
\end{document}

